    code: { lang: "python", title: "integrity.py — baseline + check modes (complete, Python 3.10+)", code: "import hashlib, json, sys\nfrom pathlib import Path\n\ndef sha256_of(path):\n    h = hashlib.sha256()\n    with open(path, 'rb') as f:\n        for chunk in iter(lambda: f.read(65536), b''):\n            h.update(chunk)\n    return h.hexdigest()\n\ndef build_baseline(folder):\n    base = {}\n    for p in sorted(Path(folder).rglob('*')):\n        if p.is_file():\n            base[str(p)] = sha256_of(p)\n    return base\n\nfolder = sys.argv[1] if len(sys.argv) > 1 else '.'\nmode = sys.argv[2] if len(sys.argv) > 2 else 'baseline'\nif mode == 'baseline':\n    data = build_baseline(folder)\n    Path('baseline.json').write_text(json.dumps(data, indent=2))\n    print(f'Baseline saved: {len(data)} files')\nelse:\n    try:\n        base = json.loads(Path('baseline.json').read_text())\n    except (FileNotFoundError, json.JSONDecodeError):\n        print('No readable baseline.json — run baseline mode first'); raise SystemExit(1)\n    now = build_baseline(folder)\n    for path, digest in base.items():\n        if path not in now: print('MISSING ', path)\n        elif now[path] != digest: print('CHANGED ', path)\n    for path in now:\n        if path not in base: print('NEW     ', path)\n    print('Check complete')", output: "Baseline saved: 3 files\n(later, after editing one file)\nCHANGED  notes.txt\nCheck complete", lines: ["iter(lambda: f.read(65536), b'') reads 64 KB chunks until the empty-bytes sentinel — flat memory at any file size.", "'rb' binary mode: hashes operate on bytes, not decoded text.", "JSON round-trip: dict → text file → dict, unchanged. Baselines must survive restarts.", "The check reports differences only — silence about unchanged files is a feature."] },
