    code: { lang: "c", title: "login_attempts.c — decisions, loops, operators (complete; gcc)", code: "#include <stdio.h>\n\nint main(void) {\n    int attempts[] = {2, 5, 41, 3, 17};\n    int n = 5;\n    int total = 0;\n    int flagged = 0;\n    for (int i = 0; i < n; i++) {\n        total += attempts[i];\n        if (attempts[i] >= 10) {\n            flagged++;\n            printf(\"source %d: %d attempts — FLAG\\n\", i, attempts[i]);\n        }\n    }\n    double average = (double)total / n;\n    printf(\"total=%d flagged=%d average=%.1f\\n\", total, flagged, average);\n    return 0;\n}", output: "source 2: 41 attempts — FLAG\nsource 4: 17 attempts — FLAG\ntotal=68 flagged=2 average=13.6", lines: ["(double)total is a cast: it forces real division, avoiding the 68/5 == 13 integer trap.", "attempts[i] indexes the array (arrays get their own lesson next; note the index starts at 0).", "%.1f prints a double with one decimal place — specifier matches type, as required.", "return 0 tells the OS 'success' — scripts and CI read this exit code."] },
